595	static void
596	format_smith_value(char *buf, int len, const float coeff[2], uint32_t frequency)
597	{
598	  // z = (gamma+1)/(gamma-1) * z0
599	  float z0 = 50;
600	  float d = z0 / ((1-coeff[0])*(1-coeff[0])+coeff[1]*coeff[1]);
601	  float zr = ((1+coeff[0])*(1-coeff[0]) - coeff[1]*coeff[1]) * d;
602	  float zi = 2*coeff[1] * d;
603	  char prefix;
604	  float value;
605	  switch (marker_smith_format) {
606	  case MS_LIN:
607	    plot_printf(buf, len, "%.2f %.1f" S_DEGREE, linear(coeff), phase(coeff));
608	    break;
609	
610	  case MS_LOG: {
611	      float v = logmag(coeff);
612	      if (v == -INFINITY)
613	        plot_printf(buf, len, "-"S_INFINITY" dB");
614	      else
615	        plot_printf(buf, len, "%.1fdB %.1f" S_DEGREE, v, phase(coeff));
616	    }
617	    break;
618	
619	  case MS_REIM:
620	    plot_printf(buf, len, "%F%+Fj", coeff[0], coeff[1]);
621	    break;
622	
623	  case MS_RX:
624	    plot_printf(buf, len, "%F%+Fj"S_OHM, zr, zi);
625	    break;
626	
627	  case MS_RLC:
628	    if (zi < 0) {// Capacity
629	      prefix = 'F';
630	      value = -1 / (2 * VNA_PI * frequency * zi);
631	    } else {
632	      prefix = 'H';
633	      value = zi / (2 * VNA_PI * frequency);
634	    }
635	    plot_printf(buf, len, "%F"S_OHM" %F%c", zr, value, prefix);
636	    break;
637	  }
638	}
