    v = gamma2resistance(coeff);
    break;
  case TRC_X:
    format = "%.2F"S_OHM;
    v = gamma2reactance(coeff);
    break;
  case TRC_Q:
    format = "%.1f";
    v = qualityfactor(coeff);
    break;
