static float distance_of_index(int idx)
{
  float distance = ((float)idx * (float)SPEED_OF_LIGHT) /
                   ((float)(frequencies[1] - frequencies[0]) * (float)FFT_SIZE * 2.0);
  return distance * velocity_factor;
}

